Lemma popbits_chk : forall_rangeZ (fun k => Z.eqb (popbits (Z.ones (k+1))) (63 - k)) 0 64 = true.
Proof. ltac2:(KReplay.run [|constr:(@Corelib.Init.Logic.eq_refl); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.eq); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.CidBits.forall_rangeZ); constr:(@Corelib.Numbers.BinNums.Z); constr:(@Stdlib.ZArith.BinInt.Z.eqb); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.As.SecMsb.popbits); constr:(@Stdlib.ZArith.BinInt.Z.ones); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Corelib.Numbers.BinNums.Zpos); constr:(@Corelib.Numbers.BinNums.xH); constr:(@Stdlib.ZArith.BinInt.Z.sub); constr:(@Corelib.Numbers.BinNums.xI); constr:(@Corelib.Numbers.BinNums.Z0); constr:(@Corelib.Numbers.BinNums.xO)|] [|@k|] "##;#$#4#2#(#)###'#0#/#.#3#-#,#+#5#*#6#4#1&#1$#2$#3$VGDE%CVHF#UI#UJ#$C$#$#$#$#%#VK#FVL*#j#$M##C##########%#WN*O#WPD#Em$9##"). Qed.

Theorem clzbits_eq : forall x, 0 < x < 2^64 -> clzbits x = 63 - Z.log2 x.
Proof.
  intros x Hx. unfold clzbits. rewrite smear_smear0, smear0_eq by lia.
  assert (Hk : 0 <= Z.log2 x < 64) by (split; [apply Z.log2_nonneg|apply Z.log2_lt_pow2; lia]).
  apply Z.eqb_eq. apply (forall_rangeZ_spec _ 0 64 (Z.log2 x) popbits_chk); lia.
Qed.

Corollary clzbits_range : forall x, 0 < x < 2^64 -> 0 <= clzbits x <= 63.
Proof. intros x Hx. rewrite clzbits_eq by lia. pose proof (Z.log2_nonneg x). assert (Z.log2 x < 64) by (apply Z.log2_lt_pow2; lia). lia. Qed.

(* [comment removed for export] *)
Lemma lxor63_sub : forall c, 0 <= c <= 63 -> Z.lxor c 63 = 63 - c.
Proof.
  intros c Hc.
  assert (E : forall_rangeZ (fun c => Z.eqb (Z.lxor c 63) (63 - c)) 0 64 = true) by (vm_compute; reflexivity).
  apply Z.eqb_eq. apply (forall_rangeZ_spec _ 0 64 c E); lia.
Qed.
